import asyncio
from playwright.async_api import async_playwright

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        context = await browser.new_context()
        page = await context.new_page()

        errors = []
        page.on("console", lambda msg: errors.append(f"[{msg.type}] {msg.text}") if msg.type == "error" else None)
        page.on("pageerror", lambda err: errors.append(f"[pageerror] {err}"))

        await page.goto("http://localhost:4173/", {"waitUntil": "networkidle"})

        # Verify globals exist
        caps = await page.evaluate("() => ({ cf: !!window.CapacitorFilesystem, fs: !!window.CapacitorFilesystem?.Filesystem, dir: !!window.CapacitorFilesystem?.Directory, enc: !!window.CapacitorFilesystem?.Encoding, run: typeof window.runDirectoryExport })")
        print("Globals:", caps)
        assert caps["cf"] and caps["fs"] and caps["dir"] and caps["enc"], "CapacitorFilesystem not exposed properly"
        assert caps["run"] == "function", "runDirectoryExport not a function"

        # Set up a source tree using the exposed Filesystem API.
        # Tree:
        #   src/
        #     a.txt            ("Hello A")
        #     b.txt            ("Hello BB")
        #     sub1/
        #       c.txt          ("Hello CCC")
        #       deep/
        #         d.txt         ("Hello DDDD")
        #     empty/            (empty directory)
        setup = await page.evaluate("""async () => {
            const { Filesystem, Directory, Encoding } = window.CapacitorFilesystem;
            const D = Directory.Data;

            // Clean up any previous run
            try { await Filesystem.rmdir({ path: 'src', directory: D, recursive: true }); } catch(e) {}
            try { await Filesystem.rmdir({ path: 'dest', directory: D, recursive: true }); } catch(e) {}
            try { await Filesystem.deleteFile({ path: 'manifest.json', directory: D }); } catch(e) {}

            // Create directories
            await Filesystem.mkdir({ path: 'src', directory: D, recursive: true });
            await Filesystem.mkdir({ path: 'src/sub1', directory: D, recursive: true });
            await Filesystem.mkdir({ path: 'src/sub1/deep', directory: D, recursive: true });
            await Filesystem.mkdir({ path: 'src/empty', directory: D, recursive: true });

            // Create files (UTF-8 text)
            await Filesystem.writeFile({ path: 'src/a.txt', data: 'Hello A', directory: D, encoding: Encoding.UTF8, recursive: true });
            await Filesystem.writeFile({ path: 'src/b.txt', data: 'Hello BB', directory: D, encoding: Encoding.UTF8, recursive: true });
            await Filesystem.writeFile({ path: 'src/sub1/c.txt', data: 'Hello CCC', directory: D, encoding: Encoding.UTF8, recursive: true });
            await Filesystem.writeFile({ path: 'src/sub1/deep/d.txt', data: 'Hello DDDD', directory: D, encoding: Encoding.UTF8, recursive: true });

            return 'setup done';
        }""")
        print("Setup:", setup)

        # Run the export
        manifest = await page.evaluate("""async () => {
            return await window.runDirectoryExport({ sourceDir: 'src', destDir: 'dest', manifestPath: 'manifest.json' });
        }""")
        print("Manifest:", manifest)

        # Verify manifest schema
        assert set(manifest.keys()) == {"files", "directories", "totalFiles", "totalBytes"}, f"Unexpected manifest keys: {manifest.keys()}"
        assert manifest["totalFiles"] == 4, f"totalFiles={manifest['totalFiles']}"
        assert manifest["totalBytes"] == 7 + 8 + 9 + 10, f"totalBytes={manifest['totalBytes']}"  # "Hello A"=7, "Hello BB"=8, "Hello CCC"=9, "Hello DDDD"=10

        # Files sorted ascending by path
        file_paths = [f["path"] for f in manifest["files"]]
        assert file_paths == sorted(file_paths), f"Files not sorted: {file_paths}"
        expected_files = {"a.txt", "b.txt", "sub1/c.txt", "sub1/deep/d.txt"}
        assert set(file_paths) == expected_files, f"File paths mismatch: {file_paths}"

        # Check sizes
        size_map = {f["path"]: f["size"] for f in manifest["files"]}
        assert size_map["a.txt"] == 7, f"a.txt size={size_map['a.txt']}"
        assert size_map["b.txt"] == 8, f"b.txt size={size_map['b.txt']}"
        assert size_map["sub1/c.txt"] == 9, f"c.txt size={size_map['sub1/c.txt']}"
        assert size_map["sub1/deep/d.txt"] == 10, f"d.txt size={size_map['sub1/deep/d.txt']}"

        # Directories sorted ascending, excluding source root
        dirs = manifest["directories"]
        assert dirs == sorted(dirs), f"Directories not sorted: {dirs}"
        expected_dirs = ["empty", "sub1", "sub1/deep"]
        assert dirs == expected_dirs, f"Directories mismatch: {dirs}"

        # Verify the manifest file was written to IndexedDB
        manifest_file = await page.evaluate("""async () => {
            const { Filesystem, Directory, Encoding } = window.CapacitorFilesystem;
            const { data } = await Filesystem.readFile({ path: 'manifest.json', directory: Directory.Data, encoding: Encoding.UTF8 });
            return data;
        }""")
        parsed = __import__("json").loads(manifest_file)
        assert parsed == manifest, "Manifest file content does not match returned manifest"

        # Verify destination tree structure and file contents (byte-for-byte)
        verify = await page.evaluate("""async () => {
            const { Filesystem, Directory, Encoding } = window.CapacitorFilesystem;
            const D = Directory.Data;
            const result = { files: {}, dirs: [] };

            async function walk(path, rel) {
                const { files } = await Filesystem.readdir({ path, directory: D });
                for (const f of files) {
                    const fp = rel ? rel + '/' + f.name : f.name;
                    if (f.type === 'directory') {
                        result.dirs.push(fp);
                        await walk(path + '/' + f.name, fp);
                    } else {
                        const { data } = await Filesystem.readFile({ path: path + '/' + f.name, directory: D, encoding: Encoding.UTF8 });
                        result.files[fp] = data;
                    }
                }
            }
            await walk('dest', '');
            return result;
        }""")
        print("Dest tree:", verify)

        # Check all files copied with correct content
        assert verify["files"]["a.txt"] == "Hello A", f"a.txt content={verify['files']['a.txt']}"
        assert verify["files"]["b.txt"] == "Hello BB"
        assert verify["files"]["sub1/c.txt"] == "Hello CCC"
        assert verify["files"]["sub1/deep/d.txt"] == "Hello DDDD"

        # Check all directories exist in dest, including empty one
        assert set(verify["dirs"]) == {"empty", "sub1", "sub1/deep"}, f"Dest dirs mismatch: {verify['dirs']}"
        assert "empty" in verify["dirs"], "Empty directory not recreated in dest"

        # Verify empty directory is actually empty
        empty_check = await page.evaluate("""async () => {
            const { Filesystem, Directory } = window.CapacitorFilesystem;
            const { files } = await Filesystem.readdir({ path: 'dest/empty', directory: Directory.Data });
            return files.length;
        }""")
        assert empty_check == 0, f"empty dir not empty: {empty_check} entries"

        if errors:
            print("CONSOLE ERRORS:", errors)
        assert not errors, f"Console errors: {errors}"

        print("\nALL TESTS PASSED ✓")
        await browser.close()

asyncio.run(main())

